let BusinessUnitAccounts = IdentityInfo
| where isnotempty(AccountObjectId)
| summarize arg_max(TimeGenerated, CompanyName) by AccountObjectId
| extend Company = replace_regex(toupper(trim(@"\s+", tostring(CompanyName))), @"\s+", " ")
| where Company in ({BusinessUnit})
| project AccountObjectId;
let BusinessUnitEvents = materialize(
    CloudAppEvents
    | where ActionType == "CopilotInteraction"
    | where 'value::all' in ({BusinessUnit}) or AccountObjectId in (BusinessUnitAccounts)
);
let JB = BusinessUnitEvents | where RawEventData has 'JailbreakDetected' | mv-apply M = parse_json(RawEventData).CopilotEventData.Messages on (where tostring(M.JailbreakDetected) =~ 'true');
let XP = BusinessUnitEvents | where RawEventData has 'XPIADetected' | mv-apply R = parse_json(RawEventData).CopilotEventData.AccessedResources on (where tostring(R.XPIADetected) =~ 'true');
let RES = BusinessUnitEvents | where RawEventData has 'CopilotEventData' | mv-expand Res = parse_json(RawEventData).CopilotEventData.AccessedResources | summarize v = todouble(dcount(tostring(Res.Name)));
union
(RES | extend Metric = 'Resources accessed', o = 1),
(JB | summarize v = todouble(count()) | extend Metric = 'Jailbreak detections', o = 2),
(XP | summarize v = todouble(count()) | extend Metric = 'XPIA detections', o = 3)
| order by o asc
| project Metric, Value = v

let BusinessUnitAccounts = IdentityInfo
| where isnotempty(AccountObjectId)
| summarize arg_max(TimeGenerated, CompanyName) by AccountObjectId
| extend Company = replace_regex(toupper(trim(@"\s+", tostring(CompanyName))), @"\s+", " ")
| where Company in ({BusinessUnit})
| project AccountObjectId;
let BusinessUnitEvents = materialize(
    CloudAppEvents
    | where ActionType == "CopilotInteraction"
    | where 'value::all' in ({BusinessUnit}) or AccountObjectId in (BusinessUnitAccounts)
);
let JB = BusinessUnitEvents | where RawEventData has 'JailbreakDetected' | mv-apply M = parse_json(RawEventData).CopilotEventData.Messages on (where tostring(M.JailbreakDetected) =~ 'true') | summarize Detections = count() by bin(Timestamp, 1d) | extend ThreatType = 'Jailbreak'; let XP = BusinessUnitEvents | where RawEventData has 'XPIADetected' | mv-apply R = parse_json(RawEventData).CopilotEventData.AccessedResources on (where tostring(R.XPIADetected) =~ 'true') | summarize Detections = count() by bin(Timestamp, 1d) | extend ThreatType = 'XPIA'; union JB, XP | order by Timestamp asc

let Identities = materialize(
    IdentityInfo
    | project TimeGenerated, AccountObjectId, AccountUPN, AccountDisplayName, CompanyName, Department
);
let idsByObj = Identities
| where isnotempty(AccountObjectId)
| summarize arg_max(TimeGenerated, AccountUPN, AccountDisplayName, CompanyName, Department) by AccountObjectId;
let idsByUpn = Identities
| where isnotempty(AccountUPN)
| summarize arg_max(TimeGenerated, AccountDisplayName, CompanyName, Department) by UPNkey = tolower(tostring(AccountUPN));
let cae = CloudAppEvents
| where ActionType == "CopilotInteraction"
| extend App = tostring(RawEventData.CopilotEventData.AppHost)
| extend App = iff(isempty(App), "[Unknown surface]", App)
| join kind=leftouter idsByObj on AccountObjectId
| project TimeGenerated, UPN = tolower(coalesce(tostring(AccountUPN), tostring(AccountId))), DisplayName = coalesce(tostring(AccountDisplayName), tostring(AccountId)), Company = CompanyName, Department, App, Source = "CloudAppEvents";
let oa = OfficeActivity
| where OfficeWorkload =~ "Copilot" or Operation =~ "CopilotInteraction"
| extend UPNkey = tolower(tostring(UserId))
| join kind=leftouter idsByUpn on UPNkey
| project TimeGenerated, UPN = UPNkey, DisplayName = coalesce(tostring(AccountDisplayName), tostring(UserId)), Company = CompanyName, Department, App = "[Surface unavailable]", Source = "OfficeActivity";
let Copilot = union isfuzzy=true cae, oa
| extend Company = iff(isempty(Company), "Unknown", replace_regex(toupper(trim(@"\s+", tostring(Company))), @"\s+", " "))
| extend Department = iff(isempty(Department), "Unknown", replace_regex(trim(@"\s+", tostring(Department)), @"\s+", " "))
| where 'value::all' in ({BusinessUnit}) or Company in ({BusinessUnit});
let Base = materialize(Copilot);
let daily = Base | summarize u = dcount(UPN) by d = bin(TimeGenerated, 1d);
let mau = toscalar(Base | summarize dcount(UPN));
let avgdau = toscalar(daily | summarize avg(u));
let power = toscalar(Base | summarize c = count() by UPN | where c >= 20 | count);
let returning = toscalar(Base | summarize days = dcount(bin(TimeGenerated, 1d)) by UPN | where days >= 2 | count);
union
(print Metric = "Active users (MAU)", Value = todouble(mau), o = 1),
(print Metric = "Avg daily active (DAU)", Value = round(avgdau, 0), o = 2),
(print Metric = "Stickiness (DAU/MAU %)", Value = iff(mau == 0, 0.0, round(100.0 * avgdau / mau, 1)), o = 3),
(print Metric = "Power users (20+)", Value = todouble(power), o = 4),
(print Metric = "Returning users (2+ days)", Value = todouble(returning), o = 5)
| order by o asc
| project Metric, Value

let SelectedUpn = tolower('{User}');
let SelectedUser = materialize(
    IdentityInfo
    | where isnotempty(SelectedUpn)
    | extend UPN = tolower(tostring(AccountUPN))
    | where UPN == SelectedUpn
    | summarize arg_max(TimeGenerated, AccountObjectId, CompanyName) by UPN
    | extend Company = replace_regex(toupper(trim(@"\s+", tostring(CompanyName))), @"\s+", " ")
    | where 'value::all' in ({BusinessUnit}) or Company in ({BusinessUnit})
    | project AccountObjectId, UPN
);
let IsInScope = isnotempty(SelectedUpn)
    and ('value::all' in ({BusinessUnit}) or toscalar(SelectedUser | count) > 0);
let SelectedObjectIds = SelectedUser
| where isnotempty(AccountObjectId)
| project AccountObjectId;
let cae = CloudAppEvents
| where ActionType == "CopilotInteraction"
| where IsInScope
| where AccountObjectId in (SelectedObjectIds)
    or tolower(tostring(AccountId)) == SelectedUpn
    or tolower(tostring(RawEventData.UserId)) == SelectedUpn
| extend App = tostring(RawEventData.CopilotEventData.AppHost)
| extend App = iff(isempty(App), "[Unknown surface]", App)
| project TimeGenerated, App, Source = "CloudAppEvents";
let oa = OfficeActivity
| where OfficeWorkload =~ "Copilot" or Operation =~ "CopilotInteraction"
| where IsInScope and tolower(tostring(UserId)) == SelectedUpn
| project TimeGenerated, App = "[Surface unavailable]", Source = "OfficeActivity";
let Copilot = union isfuzzy=true cae, oa;
Copilot
| summarize ["Interactions"] = count() by bin(TimeGenerated, {TimeRange:grain})
| order by TimeGenerated asc

